<div class="page-title-wrap"><div><span class="eyebrow">SECURITY & ACCOUNTABILITY</span><h1>Audit Log</h1><p>Immutable operational history for sensitive business changes.</p></div><a href="<?= e(url('settings')) ?>" class="btn btn-outline-secondary"><i class="fal fa-arrow-left mr-1"></i> Settings</a></div>
<section class="panel"><div class="panel-container show"><div class="panel-content"><div class="data-toolbar"><div class="input-group table-search"><div class="input-group-prepend"><span class="input-group-text bg-white"><i class="fal fa-search"></i></span></div><input class="form-control" data-table-search placeholder="Filter audit entries…"></div><span class="text-muted fs-sm"><?= count($rows) ?> most recent events</span></div><div class="table-responsive"><table class="table mb-0" data-agency-table><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Entity</th><th>ID</th><th>IP</th><th>Change summary</th></tr></thead><tbody><?php foreach($rows as $row): $changes=json_decode($row['new_values']??'',true); ?><tr data-table-row><td><?= e(date('M j, Y g:i A',strtotime($row['created_at']))) ?></td><td><?= e($row['user_name'] ?: 'System') ?></td><td><span class="badge badge-soft-primary"><?= e(str_replace('_',' ',$row['action'])) ?></span></td><td><?= e(ucwords(str_replace('_',' ',$row['entity_type']))) ?></td><td>#<?= (int)$row['entity_id'] ?></td><td class="text-muted"><?= e($row['ip_address'] ?: '—') ?></td><td class="text-muted fs-xs text-truncate" style="max-width:260px"><?= e($changes?implode(', ',array_keys($changes)):'—') ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></section>
